INSERT INTO public.regulation_articles (id, chapter_id, code, title, content, content_type, sort_order) VALUES
('chuong-v-ieu-21', 'qclv-chuong-v', 'Điều 21', 'Quan hệ công tác giữa Ban QLDA với các đơn vị tiếp nhận tài sản, hưởng lợi', '1. Phối hợp với Các đơn vị tiếp nhận tài sản, hưởng lợi tham gia vào quá trình thực hiện dự án bao gồm công tác giải phóng mặt bằng (nếu có), chuẩn bị dự án, giám sát quá trình thực hiện, tiếp nhận và duy tu bảo dưỡng, vận hành công trình. Giám đốc Ban QLDA có thẩm quyền ra quyết định thành lập các ban, tổ công tác gồm các thành phần trên để phối hợp trong quá trình triển khai thực hiện dự án và sử dụng, duy tu bảo dưỡng, vận hành công trình;

2. Các chế độ, chính sách liên quan (nếu có) của các cán bộ đơn vị hưởng lợi thực hiện theo quy định của pháp luật và quy chế của dự án.', 'text', 6),
('chuong-v-ieu-22', 'qclv-chuong-v', 'Điều 22', 'Quan hệ giữa Lãnh đạo Ban QLDA đối với các phòng thuộc Ban QLDA', '1. Giám đốc, Phó Giám đốc phụ trách lĩnh vực/các phòng, định kỳ hoặc đột xuất họp với lãnh đạo các phòng hoặc làm việc với từng phòng, để trực tiếp nghe báo cáo tình hình, chỉ đạo việc thực hiện chương trình, kế hoạch công tác của các phòng thuộc Ban QLDA;

2. Trưởng/phụ trách các phòng có trách nhiệm báo cáo kịp thời với Ban Giám đốc Ban QLDA về kết quả thực hiện, kiến nghị các vấn đề cần giải quyết liên quan đến hoạt động của phòng mình và những khó khăn vướng mắc cần tháo gỡ, kiến nghị với cấp có thẩm quyền về sửa đổi, điều chỉnh cơ chế chính sách.', 'text', 7),
('chuong-v-ieu-23', 'qclv-chuong-v', 'Điều 23', 'Quan hệ giữa các phòng trực thuộc Ban QLDA', '1. Trưởng các phòng được giao chủ trì giải quyết các vấn đề có liên quan với các phòng khác phải trao đổi ý kiến với các phòng đó. Trưởng/phụ trách các phòng được xin ý kiến có trách nhiệm trả lời theo đúng yêu cầu của phòng chủ trì;

2. Theo phân công của Ban Giám đốc Ban QLDA, Trưởng/phụ trách các phòng có trách nhiệm phối hợp thực hiện các dự án, chương trình của Ban QLDA. Đối với những vấn đề liên quan đến nhiều phòng mà vượt quá thẩm quyền giải quyết hoặc không đủ điều kiện thì Trưởng/Phụ trách phòng chủ trì báo cáo, đề xuất với lãnh đạo Ban QLDA xem xét quyết định;

3. Thực hiện theo nguyên tắc: Công việc thuộc phạm vi chức năng, nhiệm vụ của phòng nào thì phòng đó chủ trì, tham mưu; chủ động phối hợp với các phòng có liên quan để thực hiện chức năng, nhiệm vụ, quyền hạn được giao. Các phòng liên quan có trách nhiệm phối hợp, trường hợp có ý kiến khác nhau thì phòng chủ trì báo cáo Ban Giám đốc xem xét, quyết định;

4. Tuân thủ đúng Quy chế làm việc của Ban QLDA; việc phối hợp có thể bằng văn bản hoặc qua trao đổi trực tiếp đảm bảo yêu cầu về chuyên môn, chất lượng và tiến độ thời gian trong quá trình phối hợp;

5. Bảo đảm kỷ luật, kỷ cương trong hoạt động phối hợp, đề cao trách nhiệm cá nhân của Trưởng/Phụ trách phòng chủ trì và cán bộ, viên chức, người lao động của phòng được phối hợp.', 'text', 8),
('chuong-v-ieu-24', 'qclv-chuong-v', 'Điều 24', 'Các mối quan hệ khác', '1. Quan hệ làm việc giữa Giám đốc Ban QLDA với các Bộ, ngành Trung ương, Tỉnh ủy, Hội đồng nhân dân, Ủy ban nhân dân tỉnh, các cơ quan tổ chức chính trị \- xã hội, tổ chức xã hội nghề nghiệp thuộc ngành lĩnh vực thực hiện theo quy định của pháp luật và các quy định có liên quan;

2. Quan hệ giữa Lãnh đạo Ban QLDA tỉnh với Đảng ủy Ban QLDA tỉnh thực hiện theo quy định của Đảng và Quy chế làm việc của Ban Chấp hành Đảng bộ Ban QLDA;

3. Quan hệ giữa Lãnh đạo Ban QLDA tỉnh với Công đoàn Ban QLDA tỉnh được thực hiện theo Quy chế phối hợp giữa Ban Giám đốc với Công đoàn Ban QLDA tỉnh;

4. Quan hệ giữa Lãnh đạo Ban QLDA tỉnh với các tổ chức đoàn thể và cán bộ, viên chức, người lao động trong Ban QLDA:

a) Lãnh đạo Ban QLDA tỉnh tạo điều kiện thuận lợi cho Cấp ủy, các tổ chức đoàn thể hoạt động theo đúng Điều lệ, tôn chỉ mục đích; phối hợp với cấp ủy và các tổ chức quần chúng tạo điều kiện thuận lợi cho cán bộ làm việc, nâng cao trình độ chính trị, chuyên môn nghiệp vụ trong đơn vị, bảo đảm thực hiện Quy chế dân chủ trong hoạt động của cơ quan, xây dựng nề nếp văn hóa công sở và kỷ luật, kỷ cương hành chính;', 'text', 9),
('chuong-vi-ieu-25', 'qclv-chuong-vi', 'Điều 25', 'Chế độ hội họp', '1. Chế độ họp, giao ban nội bộ

a) Chế độ họp với UBND tỉnh, Chủ tịch UBND tỉnh: Thực hiện theo quy định chung của tỉnh;', 'text', 1),
('chuong-vi-ieu-26', 'qclv-chuong-vi', 'Điều 26', 'Chế độ báo cáo', '1. Ban QLDA thực hiện chế độ báo cáo định kỳ và đột xuất với UBND tỉnh, Chủ tịch UBND tỉnh và theo yêu cầu của các cơ quan có thẩm quyền;

2. Chế độ báo cáo trong nội bộ Ban QLDA

a) Phó Giám đốc báo cáo giám đốc:', 'text', 2),
('chuong-vi-ieu-27', 'qclv-chuong-vi', 'Điều 27', 'Chế độ kiểm tra, giám sát', '1. Chế độ kiểm tra, giám sát đầu tư đối với dự án được giao Chủ đầu tư

a) Tổ chức thực hiện theo dõi, kiểm tra toàn bộ quá trình đầu tư dự án theo nội dung và chỉ tiêu được phê duyệt nhằm đảm bảo mục tiêu và hiệu quả đầu tư;', 'text', 3),
('chuong-vi-ieu-28', 'qclv-chuong-vi', 'Điều 28', 'Cung cấp thông tin hoạt động trong nội bộ Ban QLDA tỉnh', 'Lãnh đạo Ban QLDA tỉnh và các phòng liên quan có trách nhiệm thông báo bằng hình thức thích hợp, thuận tiện để cán bộ Ban QLDA tỉnh nắm được những thông tin:

1. Chủ trương, chính sách của Đảng, Nhà nước, UBND tỉnh liên quan đến công việc của Ban QLDA tỉnh;

2. Tuyển dụng, đào tạo, khen thưởng, kỷ luật, nâng bậc lương, nâng ngạch, bổ nhiệm cán bộ;

3. Văn bản kết luận về việc giải quyết khiếu nại, tố cáo;

4. Nội quy, quy chế làm việc của Ban QLDA tỉnh và các văn bản liên quan khác.', 'text', 4),
('chuong-vi-ieu-29', 'qclv-chuong-vi', 'Điều 29', 'Thời gian làm việc, chế độ nghỉ phép, nghỉ việc riêng', '1. Thời gian làm việc

Cán bộ, viên chức, người lao động có trách nhiệm:

a) Thực hiện nghiêm túc thời gian làm việc theo Luật Lao động và giờ hành chính theo thông báo của UBND tỉnh; giữ gìn vệ sinh nơi làm việc, bảo quản tài sản chung của cơ quan và tài sản được giao sử dụng; sẵn sàng đáp ứng mọi yêu cầu để hoàn thành tốt nhiệm vụ được giao;', 'text', 5),
('chuong-vi-ieu-30', 'qclv-chuong-vi', 'Điều 30', 'Đi công tác trong và ngoài nước', '1. Khi Lãnh đạo Ban đi công tác, các phòng liên quan có trách nhiệm chuẩn bị nội dung, tài liệu phục vụ; Phòng Hành chính – Tổng hợp chuẩn bị điều kiện cần thiết và công tác hậu cần cho chuyến công tác;

2. Cán bộ, viên chức, người lao động đi công tác phải xây dựng chương trình, kế hoạch, trong đó ghi rõ nội dung, địa điểm (trong nước hoặc quốc gia/vùng lãnh thổ đến), thời gian công tác, trình Trưởng/Phụ trách phòng báo cáo Giám đốc xem xét, quyết định;

3. Trường hợp tham gia đoàn công tác liên ngành hoặc đoàn công tác của tỉnh, việc cử cán bộ, viên chức, người lao động tham gia phải đúng thành phần theo yêu cầu;

4. Việc đi công tác nước ngoài được thực hiện theo quy định của pháp luật và Quy chế quản lý thống nhất các hoạt động đối ngoại của tỉnh;

5. Chế độ công tác phí và các khoản chi khác thực hiện theo Quy chế chi tiêu nội bộ của Ban QLDA và quy định hiện hành của Nhà nước.', 'text', 6)
